import React, { useEffect, useRef, useState } from 'react';
import { Users, Target, Zap, Award, Linkedin, Github, Mail, X } from 'lucide-react';
import { useAuth } from '../context/AuthContext';

const AnimatedCounter = ({ target, suffix = '' }) => {
  const [count, setCount] = useState(0);
  const ref = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
          let start = 0;
          const duration = 2000;
          const increment = target / (duration / 16);

          const timer = setInterval(() => {
            start += increment;
            if (start >= target) {
              setCount(target);
              clearInterval(timer);
            } else {
              setCount(Math.floor(start));
            }
          }, 16);

          observer.disconnect();
        }
      },
      { threshold: 0.5 }
    );

    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, [target]);

  return (
    <span ref={ref}>
      {count}{suffix}
    </span>
  );
};

const stats = [
  { value: 15, suffix: '+', label: 'Projects Completed' },
  { value: 4, suffix: '', label: 'Team Members' },
  { value: 100, suffix: '%', label: 'Client Satisfaction' },
  { value: 2, suffix: '+', label: 'Years Experience' }
];

const About = () => {
  const sectionRef = useRef(null);
  const [selectedMember, setSelectedMember] = useState(null);
  const { teamMembers } = useAuth();

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('active');
          }
        });
      },
      { threshold: 0.1, rootMargin: '0px 0px -50px 0px' }
    );

    const reveals = sectionRef.current?.querySelectorAll('.reveal');
    reveals?.forEach((el) => observer.observe(el));

    return () => observer.disconnect();
  }, []);

  const values = [
    {
      icon: Target,
      title: 'Precision',
      description: 'We focus on delivering exactly what our clients need with attention to every detail.'
    },
    {
      icon: Zap,
      title: 'Innovation',
      description: 'We embrace cutting-edge technologies to create modern, future-proof solutions.'
    },
    {
      icon: Award,
      title: 'Quality',
      description: 'We never compromise on quality, ensuring robust and scalable applications.'
    },
    {
      icon: Users,
      title: 'Collaboration',
      description: 'We work closely with our clients, keeping communication transparent throughout.'
    }
  ];

  return (
    <section id="about" ref={sectionRef} className="py-24 bg-[#0a1628] relative overflow-hidden">
      {/* Background elements */}
      <div className="absolute top-0 left-0 w-full h-32 bg-gradient-to-b from-navy-900/50 to-transparent"></div>
      <div className="absolute -top-40 right-0 w-80 h-80 bg-blue-500/5 rounded-full blur-3xl"></div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Section Header */}
        <div className="text-center mb-20 reveal">
          <span className="inline-block px-4 py-2 rounded-full bg-blue-500/10 text-blue-400 text-sm font-medium mb-4">
            Who We Are
          </span>
          <h2 className="text-4xl sm:text-5xl font-bold text-white mb-6">
            Meet the <span className="gradient-text">Team</span>
          </h2>
          <p className="text-gray-400 max-w-2xl mx-auto text-lg">
            We are a passionate group of developers and designers dedicated to creating 
            exceptional digital experiences for businesses of all sizes.
          </p>
        </div>

        {/* Stats Section */}
        <div className="reveal mb-20">
          <div className="card-minimal rounded-2xl p-6 md:p-8">
            <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
              {stats.map((stat, index) => (
                <div key={index} className="text-center">
                  <div className="text-3xl md:text-4xl font-black gradient-text mb-1">
                    <AnimatedCounter target={stat.value} suffix={stat.suffix} />
                  </div>
                  <p className="text-gray-400 text-xs">{stat.label}</p>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Team Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-24">
          {teamMembers.map((member, index) => (
            <div
              key={member.name}
              className="reveal group relative cursor-pointer"
              style={{ transitionDelay: `${index * 100}ms` }}
              onClick={() => setSelectedMember(member)}
            >
              <div className="card-minimal rounded-2xl p-6 overflow-hidden h-full flex flex-col hover:border-blue-500/30 transition-colors">
                {/* Avatar */}
                <div className="w-20 h-20 rounded-2xl bg-blue-600 flex items-center justify-center mb-4 transform group-hover:scale-110 transition-transform duration-300">
                  <span className="text-2xl font-bold text-white">{member.initials}</span>
                </div>

                <h3 className="text-xl font-bold text-white mb-1 group-hover:text-blue-400 transition-colors">
                  {member.name}
                </h3>
                <p className="text-sm font-medium mb-3 text-blue-400">
                  {member.role}
                </p>
                <p className="text-gray-400 text-sm leading-relaxed flex-grow">
                  {member.description}
                </p>

                {/* Social Links */}
                <div className="flex gap-3 mt-4 pt-4 border-t border-white/10">
                  <a href={member.socials.linkedin} className="text-gray-400 hover:text-white transition-colors">
                    <Linkedin className="w-4 h-4" />
                  </a>
                  <a href={member.socials.github} className="text-gray-400 hover:text-white transition-colors">
                    <Github className="w-4 h-4" />
                  </a>
                  <a href={member.socials.email} className="text-gray-400 hover:text-white transition-colors">
                    <Mail className="w-4 h-4" />
                  </a>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Team Member Modal */}
        {selectedMember && (
          <>
            {/* Backdrop */}
            <div 
              className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50"
              onClick={() => setSelectedMember(null)}
            ></div>

            {/* Modal */}
            <div className="fixed top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-50 w-full max-w-md mx-4">
              <div className="bg-[#0f172a] rounded-2xl p-8 relative border border-blue-500/20 shadow-2xl shadow-blue-500/10">
                {/* Close Button */}
                <button
                  onClick={() => setSelectedMember(null)}
                  className="absolute top-4 right-4 w-8 h-8 rounded-full bg-white/10 flex items-center justify-center text-gray-400 hover:text-white hover:bg-white/20 transition-all"
                >
                  <X className="w-4 h-4" />
                </button>

                {/* Avatar */}
                <div className="w-24 h-24 rounded-2xl bg-blue-600 flex items-center justify-center mb-6 mx-auto">
                  <span className="text-3xl font-bold text-white">{selectedMember.initials}</span>
                </div>

                <h3 className="text-2xl font-bold text-white mb-2 text-center">{selectedMember.name}</h3>
                <p className="text-blue-400 font-medium mb-4 text-center">{selectedMember.role}</p>
                <p className="text-gray-400 text-sm leading-relaxed mb-6 text-center">{selectedMember.description}</p>

                {/* Social Links */}
                <div className="flex justify-center gap-4">
                  <a 
                    href={selectedMember.socials.linkedin} 
                    className="w-10 h-10 rounded-full bg-blue-600/20 flex items-center justify-center text-blue-400 hover:bg-blue-600 hover:text-white transition-all"
                  >
                    <Linkedin className="w-5 h-5" />
                  </a>
                  <a 
                    href={selectedMember.socials.github} 
                    className="w-10 h-10 rounded-full bg-blue-600/20 flex items-center justify-center text-blue-400 hover:bg-blue-600 hover:text-white transition-all"
                  >
                    <Github className="w-5 h-5" />
                  </a>
                  <a 
                    href={selectedMember.socials.email} 
                    className="w-10 h-10 rounded-full bg-blue-600/20 flex items-center justify-center text-blue-400 hover:bg-blue-600 hover:text-white transition-all"
                  >
                    <Mail className="w-5 h-5" />
                  </a>
                </div>
              </div>
            </div>
          </>
        )}

        {/* Values Section */}
        <div className="reveal">
          <h3 className="text-3xl font-bold text-white text-center mb-12">
            Our <span className="gradient-text">Values</span>
          </h3>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            {values.map((value, index) => (
              <div
                key={value.title}
                className="skill-card-animated bg-[#1e293b]/80 rounded-xl p-6 text-center group border border-gray-700"
                style={{ transitionDelay: `${index * 50}ms` }}
              >
                <span className="border-line-bottom"></span>
                <div className="w-14 h-14 rounded-xl bg-blue-500/10 flex items-center justify-center mx-auto mb-4 group-hover:bg-blue-500/20 transition-colors">
                  <value.icon className="w-7 h-7 text-blue-400" />
                </div>
                <h4 className="text-lg font-semibold text-white mb-2">{value.title}</h4>
                <p className="text-gray-400 text-sm">{value.description}</p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
};

export default About;
